#!/bin/bash
# Project verification, generated by swift-harness.
#   scripts/verify.sh fast   -> run before a turn ends (Stop hook). Keep it under ~2 minutes.
#   scripts/verify.sh full   -> run before merging a branch.
# Exit code 0 = pass, anything else = fail. Errors go to stdout/stderr for Claude to read.
# It never reports PASS without running at least one build or test: SwiftLint is an extra
# check, not a substitute. When a listed platform got no build or test (packages only, so
# swift test ran on this Mac alone), the result is PARTIAL, never PASS.

set -uo pipefail
cd "$(dirname "$0")/.." || exit 1

MODE="${1:-fast}"

# ---- Project settings (filled by setup, edit freely) ----
XCODE_CONTAINER="{{XCODE_CONTAINER_FLAG}}"   # e.g. -project MyApp.xcodeproj or -workspace MyApp.xcworkspace
SCHEME="{{SCHEME}}"                          # empty if the project is packages only
# shellcheck disable=SC1083 # {{LOCAL_PACKAGES}} is replaced by /swift-harness:setup
PACKAGES=({{LOCAL_PACKAGES}})                  # e.g. ("Packages/DesignSystem" "Packages/Domain"), or () for none
# shellcheck disable=SC1083 # {{PLATFORMS}} is replaced by /swift-harness:setup
PLATFORMS=({{PLATFORMS}})                       # platforms the scheme is built and tested on: ("macOS"), ("iOS") or ("macOS" "iOS")
IOS_SIMULATOR="{{IOS_SIMULATOR}}"              # simulator for iOS tests in full mode, e.g. "iPhone 16" (xcrun simctl list devices available)
# Separate DerivedData so command-line builds never fight with an open Xcode for the build database.
DERIVED_DATA=".build/DerivedData"
# Result bundles of the last run, read on a failure (build errors with file and line, failed tests
# with their messages, attachments of failing tests), and kept for you to open in Xcode.
RESULTS=".build/swift-harness/results"
# SwiftLint baseline: set to the file path once created, so only new violations count.
LINT_BASELINE=""
# ---------------------------------------------------------

case "$MODE" in
  fast | full) ;;
  *) printf 'verify: unknown mode "%s". Use fast or full.\n' "$MODE"; exit 2 ;;
esac

if [[ "$XCODE_CONTAINER$SCHEME$IOS_SIMULATOR" == *"{{"* ]] || [[ "${PACKAGES[*]-}${PLATFORMS[*]-}" == *"{{"* ]]; then
  printf 'verify: NOT CONFIGURED. scripts/verify.sh still contains {{...}} placeholders: fill in the project settings at the top.\n'
  exit 2
fi

for platform in ${PLATFORMS[@]+"${PLATFORMS[@]}"}; do
  case "$platform" in
    macOS | iOS) ;;
    *) printf 'verify: NOT CONFIGURED. Unknown platform "%s" in PLATFORMS: use macOS or iOS.\n' "$platform"; exit 2 ;;
  esac
done
if [ -n "$SCHEME" ] && [ "${#PLATFORMS[@]}" -eq 0 ]; then
  printf 'verify: NOT CONFIGURED. SCHEME is set but PLATFORMS is empty: list the platforms to build, e.g. PLATFORMS=("macOS").\n'
  exit 2
fi
if [ -n "$SCHEME" ] && [ "$MODE" = "full" ] && [[ " ${PLATFORMS[*]-} " == *" iOS "* ]] && [ -z "$IOS_SIMULATOR" ]; then
  printf 'verify: NOT CONFIGURED. iOS tests need a simulator: set IOS_SIMULATOR (see xcrun simctl list devices available).\n'
  exit 2
fi

fail=0
ran=0      # builds and test runs
linted=0   # SwiftLint runs (full mode), counted separately
skipped=""
checked=""   # platforms that got at least one build or test
tested=""    # platforms whose tests ran (fast mode only builds a scheme)
failed_on="" # platforms with a failing build or test

step() { printf '\n== %s ==\n' "$1"; }

# XCODE_CONTAINER is a flag and a path: keep the path as one argument, even with spaces.
CONTAINER_ARGS=()
if [ -n "$XCODE_CONTAINER" ]; then
  CONTAINER_ARGS=("${XCODE_CONTAINER%% *}")
  [ "${XCODE_CONTAINER#* }" = "$XCODE_CONTAINER" ] || CONTAINER_ARGS+=("${XCODE_CONTAINER#* }")
fi

# Building needs no simulator: any iOS simulator destination compiles. Tests run on the named one.
destination() { # $1 platform, $2 action
  case "$1" in
    macOS) printf 'platform=macOS' ;;
    iOS) if [ "$2" = test ]; then printf 'platform=iOS Simulator,name=%s' "$IOS_SIMULATOR"; else printf 'generic/platform=iOS Simulator'; fi ;;
  esac
}

# Prints what a failed run's result bundle holds: build errors with file and line, failed tests with
# their messages ("failed test: <id>: <message>", read by the Stop hook), and the attachments of
# failing tests exported next to it. Fails, printing nothing, when the bundle, xcresulttool or jq is
# missing, or when the bundle names no error and no failed test: the caller then shows the text.
bundle_summary() { # $1 bundle, $2 platform
  local b="$1" builds tests lines here attach count
  [ -d "$b" ] && command -v jq >/dev/null 2>&1 && xcrun --find xcresulttool >/dev/null 2>&1 || return 1
  builds="$(xcrun xcresulttool get build-results --path "$b" --compact 2>/dev/null)" || builds=""
  tests="$(xcrun xcresulttool get test-results summary --path "$b" --compact 2>/dev/null)" || tests=""
  here="$(pwd)"
  lines="$(
    { [ -z "$builds" ] || jq -r --arg a "$here/" --arg b "$(pwd -P)/" '
        .errors[]? | (.sourceURL // "") as $u
        | ($u | capture("^file://(?<p>[^#]*)(#.*StartingLineNumber=(?<l>[0-9]+))?") // null) as $m
        | if $m == null then "error: \(.message)"
          else ($m.p | gsub("%20"; " ") | ltrimstr($a) | ltrimstr($b) | ltrimstr($a | sub("^/private"; ""))) as $f
          | "error: \($f)\(if $m.l then ":\(($m.l | tonumber) + 1)" else "" end): \(.message)" end' <<<"$builds" 2>/dev/null
      [ -z "$tests" ] || jq -r '.testFailures[]? | "failed test: \(.targetName)/\(.testIdentifierString): \(.failureText | gsub("\n"; " "))"' <<<"$tests" 2>/dev/null
    } | head -60
  )"
  [ -n "$lines" ] || return 1
  printf 'results from the result bundle (%s):\n%s\n' "$b" "$lines"
  attach="$RESULTS/attachments-$2"
  rm -rf "$attach"
  if [ -n "$tests" ] && xcrun xcresulttool export attachments --path "$b" --output-path "$attach" --only-failures >/dev/null 2>&1; then
    count="$(find "$attach" -type f ! -name manifest.json 2>/dev/null | wc -l | tr -d ' ')"
    [ "$count" -eq 0 ] || printf 'attachments of failing tests (%s file(s), screenshots included): %s\n' "$count" "$attach"
  fi
  return 0
}

run_xcodebuild() { # $1 action, $2 platform
  local action="$1" dest bundle log code
  dest="$(destination "$2" "$1")"
  bundle="$RESULTS/$action-$2.xcresult"
  # xcodebuild refuses a bundle path that exists.
  rm -rf "$bundle"
  mkdir -p "$RESULTS"
  if command -v xcbeautify >/dev/null 2>&1; then
    xcodebuild ${CONTAINER_ARGS[@]+"${CONTAINER_ARGS[@]}"} -scheme "$SCHEME" -destination "$dest" \
      -derivedDataPath "$DERIVED_DATA" -resultBundlePath "$bundle" "$action" 2>&1 | xcbeautify --quiet
    code="${PIPESTATUS[0]}"
    [ "$code" -eq 0 ] || bundle_summary "$bundle" "$2" || true
    return "$code"
  fi
  log="$(mktemp "${TMPDIR:-/tmp}/verify-xcodebuild.XXXXXX")" || return 1
  xcodebuild ${CONTAINER_ARGS[@]+"${CONTAINER_ARGS[@]}"} -scheme "$SCHEME" -destination "$dest" \
    -derivedDataPath "$DERIVED_DATA" -resultBundlePath "$bundle" -quiet "$action" >"$log" 2>&1
  code=$?
  if [ "$code" -ne 0 ] && ! bundle_summary "$bundle" "$2"; then
    # The text of xcodebuild, when the bundle cannot be read. Xcode 27 with -quiet names failed tests
    # only under "Failing tests:", one per indented line.
    printf "results from xcodebuild's text (the result bundle could not be read):\n"
    grep -E 'error:|FAILED|Test Case .* failed|Testing failed|Build failed|^Failing tests:|^[[:space:]]+[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z_][A-Za-z0-9_]*)+\(\)$' "$log" | head -80
  fi
  rm -f "$log"
  return "$code"
}

note_platform() { # $1 list name (checked or failed_on), $2 platform: adds it once
  local list="${!1}"
  case " $list " in *" $2 "*) ;; *) printf -v "$1" '%s' "${list:+$list }$2" ;; esac
}

# ${PACKAGES[@]+...} keeps an empty list working under set -u in macOS bash 3.2.
for pkg in ${PACKAGES[@]+"${PACKAGES[@]}"}; do
  step "swift test: $pkg"
  if [ ! -d "$pkg" ]; then
    printf 'package folder not found: %s (fix PACKAGES in scripts/verify.sh)\n' "$pkg"
    fail=1
    continue
  fi
  ran=$((ran + 1))
  note_platform checked macOS
  note_platform tested macOS
  swift test --package-path "$pkg" 2>&1 | tail -40
  [ "${PIPESTATUS[0]}" -eq 0 ] || { fail=1; note_platform failed_on macOS; }
done

if [ -n "$SCHEME" ]; then
  if ! command -v xcodebuild >/dev/null 2>&1; then
    step "xcodebuild ($SCHEME)"
    printf 'xcodebuild not found: install Xcode or run xcode-select.\n'
    fail=1
  else
    action="build"
    [ "$MODE" = "full" ] && action="test"
    for platform in "${PLATFORMS[@]}"; do
      step "xcodebuild $action ($SCHEME, $platform)"
      ran=$((ran + 1))
      note_platform checked "$platform"
      [ "$action" = test ] && note_platform tested "$platform"
      run_xcodebuild "$action" "$platform" || { fail=1; note_platform failed_on "$platform"; }
    done
  fi
fi

if [ "$MODE" = "full" ]; then
  if command -v swiftlint >/dev/null 2>&1; then
    step "swiftlint (strict)"
    linted=1
    if [ -n "$LINT_BASELINE" ]; then
      swiftlint lint --quiet --strict --baseline "$LINT_BASELINE" || fail=1
    else
      swiftlint lint --quiet --strict || fail=1
    fi
  else
    skipped="$skipped swiftlint(not-installed)"
  fi
fi

[ -z "$skipped" ] || printf '\nskipped:%s\n' "$skipped"

# One line for the swift-harness hooks, versioned: the outcome and the platforms checked (built or
# tested), tested and not checked. It can only lower the outcome the exit code gives, never raise it.
result_line() { # $1 outcome, $2 platforms not checked
  local list
  list() { [ -n "$1" ] && printf '%s' "${1// /, }" || printf 'none'; }
  printf 'swift-harness-result/1: %s; checked: %s; tested: %s; not checked: %s\n' "$1" "$(list "$checked")" "$(list "$tested")" "${2:-none}"
}

if [ "$fail" -ne 0 ]; then
  printf '\nverify %s: FAIL%s\n' "$MODE" "${failed_on:+ (failed on: ${failed_on// /, })}"
  result_line failed
  exit 1
fi
if [ "$ran" -eq 0 ]; then
  printf '\nverify %s: NOT CONFIGURED. No scheme and no package to check: set SCHEME or PACKAGES in scripts/verify.sh.\n' "$MODE"
  exit 2
fi
unchecked=""
for platform in ${PLATFORMS[@]+"${PLATFORMS[@]}"}; do
  case " $checked " in *" $platform "*) ;; *) unchecked="${unchecked:+$unchecked, }$platform" ;; esac
done
if [ -n "$unchecked" ]; then
  # Exit 0: nothing failed, and Claude cannot add the missing platform by itself.
  printf '\nverify %s: PARTIAL (passed on %s; not checked on %s: no SCHEME builds it, and swift test runs on this Mac only)\n' \
    "$MODE" "${checked// /, }" "$unchecked"
  result_line partial "$unchecked"
  exit 0
fi
printf '\nverify %s: PASS (%s build/test check(s)%s; platforms: %s)\n' "$MODE" "$ran" \
  "$([ "$linted" -eq 0 ] || echo ' + SwiftLint')" "${checked// /, }"
result_line passed
exit 0
